#!/usr/bin/env node
/**
 * `link-wine-corpus` — symlink the full wine corpus into every app's static-asset directory.
 *
 * @remarks
 * The wine apps stream the ~130k-row corpus from a root-relative URL (`/data-real-full.ndjson`,
 * falling back to `/data-real-full.json`). Those files are ~116MB each, generated by
 * `pnpm regen:wine:real`, and gitignored — so every app needs a symlink from its own static directory
 * to the one copy in `mock-data`, rather than six real copies.
 *
 * **Why this script exists.** Links made by hand leave nothing recording that they are needed, and
 * the failure mode when they are missing is silent: the
 * corpus loader treats an unavailable tier as "fall back to the bundled 10k default", which is BELOW
 * `WORKER_THRESHOLD`. So the app boots, filters correctly, and simply never uses the worker at all.
 * Nothing errors; the tier you were trying to demonstrate just is not there.
 *
 * **Angular gets a HARD link, and that is not a style choice.** `@angular/build`'s dev server does
 * not serve symlinked files out of `public/`: a real file (`mark.svg`) returns 206 with its real
 * content type, while a symlinked `data-real-full.ndjson` returns the SPA fallback — 200, `text/html`,
 * 1345 bytes of index.html. `loadWineCorpus` then parses HTML, finds no records, treats the tier as
 * unavailable and silently drops to the bundled 10k. Vite serves the identical symlink at 206, which
 * is why the other five are fine.
 *
 * An `angular.json` asset entry pointing at `mock-data` is not an alternative: the builder rejects it
 * outright: "The ../mock-data/src/wine asset path must be within the workspace root."
 *
 * A hard link costs no extra disk (same inode) and is indistinguishable from a real file to any
 * server. Its one weakness is staleness — regenerating the corpus writes a NEW inode, leaving the
 * link on the old one — so the hard-link branch compares inodes rather than mere existence, and
 * re-links when they diverge. That check is the whole reason this is not just `existsSync`.
 *
 * Idempotent: existing correct links are left alone, and a missing corpus is reported rather than
 * linked to nothing (a dangling symlink would serve a 404 that reads exactly like a routing bug).
 *
 * Usage: `pnpm link:wine-corpus`
 */

import { existsSync, linkSync, lstatSync, readlinkSync, statSync, symlinkSync, unlinkSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
/**
 * The engine repo, checked out beside this one.
 *
 * @remarks
 * 🔴 The corpus is GENERATED in the engine repo, not here: `@filter-enginez/mock-data` owns both the
 * generator and the gitignored Kaggle scrape cache it reads, and its published tarball deliberately
 * excludes the corpus — shipping it once made that package 716 MB. So these apps link to it across the
 * sibling checkout, which is the layout the workspace uses (`filterenginez/filter-enginez` beside
 * `filterenginez/filter-enginez-examples`). Targets are written RELATIVE, so nothing here encodes a
 * machine-specific absolute path.
 */
const ENGINE_ROOT = resolve(REPO_ROOT, '../filter-enginez');
const CORPUS_DIR = join(ENGINE_ROOT, 'packages/mock-data/src/wine');
const FILES = ['data-real-full.json', 'data-real-full.ndjson'];

/**
 * Each app's static-asset directory, by the convention its bundler expects.
 *
 * @remarks
 * One entry per wine-serving app. This list, the `.gitignore` entries beside it and
 * `tests/tooling/wineCorpusLinks.test.ts` move together; that test fails if a directory here does not
 * exist or a link here is not gitignored.
 */
const TARGET_DIRS = [
	'packages/examples-react-rtk/public',
	'packages/examples-react-plain/public',
	'packages/examples-sveltekit/static',
	'packages/examples-vue/public',
	'packages/examples-angular/public',
	'packages/examples-vanilla/public',
];

/**
 * Directories that need a HARD link instead of a symlink.
 *
 * @remarks
 * `@angular/build`'s dev server does not serve symlinks from `public/` — see the module docblock for
 * the measured evidence. Everything else takes a symlink, which is self-documenting in `ls -l` and
 * cannot go stale.
 */
const HARD_LINK_DIRS = new Set(['packages/examples-angular/public']);

let linked = 0;
let skipped = 0;
const missing = [];

for (const file of FILES) {
	const source = join(CORPUS_DIR, file);

	if (!existsSync(source)) {
		missing.push(file);

		continue;
	}

	const sourceInode = statSync(source).ino;

	for (const dir of TARGET_DIRS) {
		const linkPath = join(REPO_ROOT, dir, file);
		const relativeTarget = relative(join(REPO_ROOT, dir), source);
		const wantsHardLink = HARD_LINK_DIRS.has(dir);

		if (existsSync(linkPath) || lstatSync(linkPath, { throwIfNoEntry: false })) {
			// A dangling link still reports as an lstat hit, so compare what is actually there and
			// repair rather than assuming any existing entry is correct.
			const stats = lstatSync(linkPath);
			const isCorrect = wantsHardLink
				// Inode equality, NOT existence: a regenerated corpus writes a new inode and leaves the
				// old hard link intact and stale, which is invisible to every other check.
				? !stats.isSymbolicLink() && existsSync(linkPath) && statSync(linkPath).ino === sourceInode
				: stats.isSymbolicLink() && readlinkSync(linkPath) === relativeTarget;

			if (isCorrect) {
				skipped += 1;

				continue;
			}
			unlinkSync(linkPath);
		}

		if (wantsHardLink) {
			linkSync(source, linkPath);
		} else {
			symlinkSync(relativeTarget, linkPath);
		}
		linked += 1;
		console.log(`  ${wantsHardLink ? 'hard-linked' : 'linked'} ${dir}/${file}`);
	}
}

if (missing.length > 0) {
	console.error(`\n✖ Corpus not generated: ${missing.join(', ')}`);
	console.error(`  Looked in ${CORPUS_DIR}.`);
	console.error('  The corpus lives in the ENGINE repo. Generate it there first:');
	console.error('    cd ../filter-enginez && pnpm --filter @filter-enginez/mock-data regen:wine:real --accept-data-license');
	console.error('  (~116MB per file. The data is CC BY-NC-SA 4.0 — non-commercial — and stays on this machine.)');
	console.error('  Without it the wine routes silently fall back to the bundled 10k tier, which is');
	console.error('  BELOW the worker threshold — so the worker tier never runs and nothing errors.');
	process.exit(1);
}

console.log(`\n✔ Wine corpus linked (${linked} created, ${skipped} already correct).`);
